                  <span
                    className="inline-block h-2 w-2 rounded-full"
                    style={{ background: COLORS.rowCrop }}
                  />
                  Row-crop
                </span>
                <span className="inline-flex items-center gap-1">
                  <span
                    className="inline-block h-2 w-2 rounded-full"
                    style={{ background: COLORS.cattle }}
                  />
                  Cattle
                </span>
                <span className="inline-flex items-center gap-1">
                  <span
                    className="inline-block h-2 w-2 rounded-full"
                    style={{ background: COLORS.specialty }}
                  />
                  Specialty / urban
                </span>
                <span className="inline-flex items-center gap-1">
                  <span
                    className="inline-block h-2 w-2 rounded-full"
                    style={{ background: COLORS.mixed }}
                  />
                  Mixed
                </span>
              </div>
            </div>
          )}

          {panel === "yield-stress" && (
            <div className="grid gap-6 lg:grid-cols-2">
              <div className="h-[340px] w-full">
                <p className="mb-2 px-2 text-sm font-medium text-stone-700">
                  Implied rent yield (2025 cash rent ?? cropland value)
                </p>
                <ResponsiveContainer width="100%" height="90%">
                  <BarChart
                    data={[...RENT_YIELD_STRESS].sort(
                      (a, b) => a.yieldPct - b.yieldPct,
                    )}
                    layout="vertical"
                    margin={{ left: 8, right: 16 }}
                  >
                    <CartesianGrid strokeDasharray="3 3" stroke="#e7e5e4" />
                    <XAxis
                      type="number"
                      tick={{ fontSize: 12 }}
                      tickFormatter={(v) => `${v}%`}
                      domain={[0, 4.5]}
                    />
                    <YAxis
                      type="category"
                      dataKey="region"
                      width={100}
                      tick={{ fontSize: 11 }}
                    />
                    <ReferenceLine
                      x={3.5}
                      stroke={COLORS.accent}
                      strokeDasharray="4 4"
                      label={{
                        value: "3.5% stress",
                        fill: COLORS.accent,
                        fontSize: 10,
                      }}
                    />
                    <Tooltip
                      formatter={(v) =>
                        typeof v === "number" ? `${v.toFixed(2)}%` : v
                      }
                    />
                    <Bar
                      dataKey="yieldPct"
                      name="Yield %"
                      fill={COLORS.cropland}
                      radius={[0, 4, 4, 0]}
                    />
                  </BarChart>
                </ResponsiveContainer>
              </div>
              <div className="h-[340px] w-full">
                <p className="mb-2 px-2 text-sm font-medium text-stone-700">
                  Value compression if yields reprice to 3.5%
                </p>
                <ResponsiveContainer width="100%" height="90%">
                  <BarChart
                    data={RENT_YIELD_STRESS}
                    layout="vertical"
                    margin={{ left: 8, right: 16 }}
                  >
                    <CartesianGrid strokeDasharray="3 3" stroke="#e7e5e4" />
                    <XAxis
                      type="number"
                      tick={{ fontSize: 12 }}
                      tickFormatter={(v) => `${v}%`}
                    />
                    <YAxis
                      type="category"
                      dataKey="region"
                      width={100}
                      tick={{ fontSize: 11 }}
                    />
                    <Tooltip
                      formatter={(v) =>
                        typeof v === "number" ? fmtPct(v) : v
                      }
                    />
                    <Bar
                      dataKey="compressionPct"
                      name="Value ?? at 3.5%"
                      fill={COLORS.stress}
                      radius={[0, 4, 4, 0]}
                    />
                  </BarChart>
                </ResponsiveContainer>
              </div>
            </div>
          )}

          {panel === "rate-bands" && (
            <div className="h-[360px] w-full">
              <p className="mb-2 px-2 text-sm font-medium text-stone-700">
                National implied cropland value under rent-yield shifts
              </p>
              <ResponsiveContainer width="100%" height="88%">
                <ComposedChart data={RATE_BANDS}>
                  <CartesianGrid strokeDasharray="3 3" stroke="#e7e5e4" />
                  <XAxis dataKey="label" tick={{ fontSize: 11 }} />
                  <YAxis
                    yAxisId="left"
                    tick={{ fontSize: 12 }}
                    tickFormatter={(v) => `$${(v / 1000).toFixed(1)}k`}
                  />
                  <YAxis
                    yAxisId="right"
                    orientation="right"
                    tick={{ fontSize: 12 }}
                    domain={[50, 170]}
                    tickFormatter={(v) => `${v}`}
                  />
                  <Tooltip
                    formatter={(v, name) => [
                      typeof v === "number"
                        ? name === "impliedUsValue"
                          ? fmtDollar(v)
                          : v.toFixed(1)
                        : v,
                      name === "impliedUsValue" ? "$/acre" : "Index (base=100)",
                    ]}
                  />
                  <Legend />
                  <Bar
                    yAxisId="left"
                    dataKey="impliedUsValue"
                    name="Implied $/acre"
                    fill={COLORS.navy}
                    radius={[4, 4, 0, 0]}
                  />
                  <Line
                    yAxisId="right"
                    type="monotone"
                    dataKey="index"
                    name="Index"
                    stroke={COLORS.accent}
                    strokeWidth={2.5}
                    dot={{ r: 4 }}
                  />
                </ComposedChart>
              </ResponsiveContainer>
              <p className="mt-2 px-2 text-xs text-stone-500">
                +100 bp on the implied yield maps to roughly a{" "}
                {ANALYTICS.plus100bpImpliedDropPct}% haircut vs the 2025 survey
                average ??? a scenario, not a NASS forecast.
              </p>
            </div>
          )}
        </div>

        <figcaption className="border-t border-stone-200 bg-stone-50 px-4 py-3 text-xs leading-relaxed text-stone-500 sm:px-6">
          {SOURCE_NOTE}
        </figcaption>
      </div>
    </figure>
  );
}

